def count_adjacent_special(grid, r, c, special_val):
    """Count orthogonal neighbors with the special value"""
    count = 0
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == special_val:
                count += 1
    return count

def apply_transformation(grid, bg_val, sparse_val):
    """Apply the transformation: bg_val with 2+ adjacent sparse_val becomes 3"""
    result = [row[:] for row in grid]

