                                size += 1
                                visited[nr][nc] = True
                # Re-traverse to set component size for ALL cells in component
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    for nr in [r for r in range(max(0,cr-1), min(rows,cr+2))]:
                        for nc in [c for c in range(max(0,cc-1), min(cols,cc+2))]:
                            if grid[nr][nc] == 6:
